// Production-optimized Mobile Optimization JavaScript
class MobileOptimization {
    constructor() {
        try {
            this.isMobile = window.innerWidth <= 768;
            this.touchStartX = 0;
            this.touchStartY = 0;
            this.touchEndX = 0;
            this.touchEndY = 0;
            this.minSwipeDistance = 50;
            this.init();
        } catch (error) {
            // Silently handle initialization errors
        }
    }

    init() {
        try {
            this.setupMobileDetection();
            this.setupTouchInteractions();
            this.setupMobileNavigation();
            this.setupMobileCarousel();
            this.setupPerformanceOptimizations();
            this.setupAccessibilityEnhancements();
            this.setupMobileAnalytics();
        } catch (error) {
            // Silently handle initialization errors
        }
    }

    setupMobileDetection() {
        try {
            // Add mobile class to body for CSS targeting
            if (this.isMobile) {
                document.body.classList.add('mobile-device');
            }

            // Handle orientation changes
            window.addEventListener('orientationchange', () => {
                setTimeout(() => {
                    this.handleOrientationChange();
                }, 100);
            });

            // Handle resize events
            let resizeTimeout;
            window.addEventListener('resize', () => {
                clearTimeout(resizeTimeout);
                resizeTimeout = setTimeout(() => {
                    this.handleResize();
                }, 250);
            });
        } catch (error) {
            // Silently handle errors
        }
    }

    handleOrientationChange() {
        try {
            // Recalculate carousel dimensions
            this.updateCarouselDimensions();
            
            // Update mobile detection
            this.isMobile = window.innerWidth <= 768;
            
            // Trigger resize event for CSS updates
            window.dispatchEvent(new Event('resize'));
        } catch (error) {
            // Silently handle errors
        }
    }

    handleResize() {
        try {
            const wasMobile = this.isMobile;
            this.isMobile = window.innerWidth <= 768;
            
            // Update body class if mobile state changed
            if (wasMobile !== this.isMobile) {
                document.body.classList.toggle('mobile-device', this.isMobile);
            }
            
            // Update carousel dimensions
            this.updateCarouselDimensions();
        } catch (error) {
            // Silently handle errors
        }
    }

    setupTouchInteractions() {
        try {
            // Enhanced touch feedback for buttons
            this.setupTouchFeedback();
            
            // Swipe gestures for navigation
            this.setupSwipeGestures();
            
            // Touch-optimized scrolling
            this.setupTouchScrolling();
            
            // Prevent zoom on double tap
            this.preventDoubleTapZoom();
        } catch (error) {
            // Silently handle errors
        }
    }

    setupTouchFeedback() {
        try {
            const touchElements = document.querySelectorAll('.btn, .nav-toggle, .nav-menu a, .project-card, .experience-item');
            
            touchElements.forEach(element => {
                element.addEventListener('touchstart', (e) => {
                    element.classList.add('touch-active');
                }, { passive: true });
                
                element.addEventListener('touchend', (e) => {
                    setTimeout(() => {
                        element.classList.remove('touch-active');
                    }, 150);
                }, { passive: true });
            });
        } catch (error) {
            // Silently handle errors
        }
    }

    setupSwipeGestures() {
        try {
            document.addEventListener('touchstart', (e) => {
                this.touchStartX = e.changedTouches[0].screenX;
                this.touchStartY = e.changedTouches[0].screenY;
            }, { passive: true });

            document.addEventListener('touchend', (e) => {
                this.touchEndX = e.changedTouches[0].screenX;
                this.touchEndY = e.changedTouches[0].screenY;
                this.handleSwipe();
            }, { passive: true });
        } catch (error) {
            // Silently handle errors
        }
    }

    handleSwipe() {
        try {
            const deltaX = this.touchEndX - this.touchStartX;
            const deltaY = this.touchEndY - this.touchStartY;
            
            if (Math.abs(deltaX) > Math.abs(deltaY) && Math.abs(deltaX) > this.minSwipeDistance) {
                if (deltaX > 0) {
                    // Swipe right - could be used for navigation
                    this.handleSwipeRight();
                } else {
                    // Swipe left - could be used for navigation
                    this.handleSwipeLeft();
                }
            }
        } catch (error) {
            // Silently handle errors
        }
    }

    handleSwipeRight() {
        // Could be used for navigation or other interactions
    }

    handleSwipeLeft() {
        // Could be used for navigation or other interactions
    }

    setupTouchScrolling() {
        try {
            // Enable smooth scrolling on mobile
            document.documentElement.style.scrollBehavior = 'smooth';
            
            // Optimize scroll performance
            let ticking = false;
            window.addEventListener('scroll', () => {
                if (!ticking) {
                    requestAnimationFrame(() => {
                        this.handleScroll();
                        ticking = false;
                    });
                    ticking = true;
                }
            }, { passive: true });
        } catch (error) {
            // Silently handle errors
        }
    }

    handleScroll() {
        try {
            // Handle scroll-based animations and effects
            const scrolled = window.pageYOffset;
            const parallaxElements = document.querySelectorAll('.parallax');
            
            parallaxElements.forEach(element => {
                const speed = element.dataset.speed || 0.5;
                element.style.transform = `translateY(${scrolled * speed}px)`;
            });
        } catch (error) {
            // Silently handle errors
        }
    }

    preventDoubleTapZoom() {
        try {
            let lastTouchEnd = 0;
            document.addEventListener('touchend', (event) => {
                const now = (new Date()).getTime();
                if (now - lastTouchEnd <= 300) {
                    event.preventDefault();
                }
                lastTouchEnd = now;
            }, false);
        } catch (error) {
            // Silently handle errors
        }
    }

    setupMobileNavigation() {
        try {
            const navToggle = document.querySelector('.nav-toggle');
            const navMenu = document.querySelector('.nav-menu');
            
            if (navToggle && navMenu) {
                navToggle.addEventListener('click', () => {
                    const isExpanded = navToggle.getAttribute('aria-expanded') === 'true';
                    navToggle.setAttribute('aria-expanded', !isExpanded);
                    navMenu.classList.toggle('active');
                });
                
                // Close menu when clicking outside
                document.addEventListener('click', (e) => {
                    if (!navToggle.contains(e.target) && !navMenu.contains(e.target)) {
                        navToggle.setAttribute('aria-expanded', 'false');
                        navMenu.classList.remove('active');
                    }
                });
            }
        } catch (error) {
            // Silently handle errors
        }
    }

    setupMobileCarousel() {
        try {
            // Initialize mobile carousel if present
            const carousel = document.querySelector('.carousel');
            if (carousel) {
                this.updateCarouselDimensions();
            }
        } catch (error) {
            // Silently handle errors
        }
    }

    updateCarouselDimensions() {
        try {
            const carousel = document.querySelector('.carousel');
            if (carousel && this.isMobile) {
                const container = carousel.querySelector('.carousel-container');
                if (container) {
                    const itemWidth = container.offsetWidth;
                    container.style.setProperty('--item-width', `${itemWidth}px`);
                }
            }
        } catch (error) {
            // Silently handle errors
        }
    }

    setupPerformanceOptimizations() {
        try {
            // Lazy load images
            this.setupLazyLoading();
            
            // Optimize animations
            this.optimizeAnimations();
            
            // Reduce repaints
            this.reduceRepaints();
        } catch (error) {
            // Silently handle errors
        }
    }

    setupLazyLoading() {
        try {
            const images = document.querySelectorAll('img[data-src]');
            const imageObserver = new IntersectionObserver((entries, observer) => {
                entries.forEach(entry => {
                    if (entry.isIntersecting) {
                        const img = entry.target;
                        img.src = img.dataset.src;
                        img.classList.remove('lazy');
                        observer.unobserve(img);
                    }
                });
            });
            
            images.forEach(img => imageObserver.observe(img));
        } catch (error) {
            // Silently handle errors
        }
    }

    optimizeAnimations() {
        try {
            // Use transform and opacity for better performance
            const animatedElements = document.querySelectorAll('.animate-on-scroll');
            
            const animationObserver = new IntersectionObserver((entries) => {
                entries.forEach(entry => {
                    if (entry.isIntersecting) {
                        entry.target.classList.add('animated');
                    }
                });
            });
            
            animatedElements.forEach(el => animationObserver.observe(el));
        } catch (error) {
            // Silently handle errors
        }
    }

    reduceRepaints() {
        try {
            // Use transform instead of changing layout properties
            const elements = document.querySelectorAll('.mobile-optimized');
            elements.forEach(element => {
                element.style.willChange = 'transform';
            });
        } catch (error) {
            // Silently handle errors
        }
    }

    setupAccessibilityEnhancements() {
        try {
            // Improve focus management
            this.setupFocusManagement();
            
            // Add ARIA labels
            this.addAriaLabels();
            
            // Improve keyboard navigation
            this.setupKeyboardNavigation();
        } catch (error) {
            // Silently handle errors
        }
    }

    setupFocusManagement() {
        try {
            const focusableElements = document.querySelectorAll('a, button, input, textarea, select, [tabindex]:not([tabindex="-1"])');
            
            focusableElements.forEach(element => {
                element.addEventListener('focus', () => {
                    element.classList.add('focused');
                });
                
                element.addEventListener('blur', () => {
                    element.classList.remove('focused');
                });
            });
        } catch (error) {
            // Silently handle errors
        }
    }

    addAriaLabels() {
        try {
            // Add missing ARIA labels for better accessibility
            const buttons = document.querySelectorAll('button:not([aria-label])');
            buttons.forEach(button => {
                if (button.textContent.trim()) {
                    button.setAttribute('aria-label', button.textContent.trim());
                }
            });
        } catch (error) {
            // Silently handle errors
        }
    }

    setupKeyboardNavigation() {
        try {
            // Improve keyboard navigation for mobile
            document.addEventListener('keydown', (e) => {
                if (e.key === 'Escape') {
                    // Close mobile menu on escape
                    const navToggle = document.querySelector('.nav-toggle');
                    const navMenu = document.querySelector('.nav-menu');
                    if (navToggle && navMenu) {
                        navToggle.setAttribute('aria-expanded', 'false');
                        navMenu.classList.remove('active');
                    }
                }
            });
        } catch (error) {
            // Silently handle errors
        }
    }

    setupMobileAnalytics() {
        try {
            // Track mobile-specific interactions
            this.trackMobileInteractions();
            
            // Monitor performance on mobile
            this.monitorMobilePerformance();
        } catch (error) {
            // Silently handle errors
        }
    }

    trackMobileInteractions() {
        try {
            // Track touch interactions
            const touchElements = document.querySelectorAll('.btn, .nav-toggle');
            touchElements.forEach(element => {
                element.addEventListener('touchstart', () => {
                    // Could send analytics data here
                }, { passive: true });
            });
        } catch (error) {
            // Silently handle errors
        }
    }

    monitorMobilePerformance() {
        try {
            // Monitor mobile performance metrics
            if ('performance' in window) {
                window.addEventListener('load', () => {
                    setTimeout(() => {
                        const perfData = performance.getEntriesByType('navigation')[0];
                        if (perfData) {
                            // Could send performance data to analytics
                        }
                    }, 1000);
                });
            }
        } catch (error) {
            // Silently handle errors
        }
    }
}

// Initialize mobile optimization
document.addEventListener('DOMContentLoaded', () => {
    try {
        new MobileOptimization();
    } catch (error) {
        // Silently handle initialization errors
    }
});
